// pattern families: each drawing fades from its first pattern (top) to its last (bottom)
const PATTERN_SETS: Record<string, string[]> = {
  a: ["solid", "checker", "dots"],
  b: ["grid", "diagonal", "dots"],
  c: ["solid", "lines", "checker"],
  d: ["checker", "grid", "fine"],
  e: ["diagonal", "solid", "lines"],
};

function PixelArt({
  shape,
  rows: customRows,
  cell,
  set = "a",
  tone = "ink",
  className = "",
}: {
  shape: string;
  rows?: string[];
  cell: number;
  set?: string;
  tone?: "ink" | "green" | "grey";
  className?: string;
}) {
  const rows = customRows ?? PIXELS[shape] ?? PIXELS.spark;
  const width = Math.max(...rows.map((row) => row.length));
  const patterns = PATTERN_SETS[set] ?? PATTERN_SETS.a;
  return (
    <span
      className={`pixel-art tone-${tone} ${className}`}
      style={{ gridTemplateColumns: `repeat(${width}, ${cell}px)`, gridAutoRows: `${cell}px`, "--cell": `${cell}px` } as React.CSSProperties}
      aria-hidden="true"
    >
      {rows.flatMap((row, y) =>
        [...row.padEnd(width, ".")].map((value, x) => {
          if (value !== "#") return <i key={`${x}-${y}`} />;
          const pattern = patterns[Math.min(patterns.length - 1, Math.floor((y / rows.length) * patterns.length))];
          return <i key={`${x}-${y}`} className={`px px-${pattern}`} />;
        }),
      )}
    </span>
  );
}

function LensIcon({ lens, on = false }: { lens: string; on?: boolean }) {
  return <PixelArt shape={`icon-${lens}`} cell={3} set="a" tone={on ? "green" : "ink"} className="lens-icon" />;
}

/* ---------- app ---------- */
const lensOrder = ["systems", "learning", "visual", "art", "research"] as const;
type Lens = (typeof lensOrder)[number];
type Work = (typeof CONTENT_FALLBACK.works)[number];
type IndexRow = {
  work?: string;
  year: number;
  title: string;
  type: string;
  context: string;
  lenses: Lens[];
  image_url?: string;
  link?: string;
};

const content = ({ ...CONTENT_FALLBACK, ...((dataFiles["./data/content.json"] as object | undefined) ?? {}) }) as typeof CONTENT_FALLBACK & {
  lenses: Record<Lens, { label: string; subtitle: string; line: string; bug: string }>;
};

function lensesFromLocation(): Lens[] {
  const fallback = new URLSearchParams(window.location.search).get("v") ?? "";
  const hash = window.location.hash.replace(/^#\/?/, "");
  const raw = hash.startsWith("work/") ? fallback : hash || fallback;
  return raw.split("+").filter((value): value is Lens => lensOrder.includes(value as Lens));
}

function storyPageFromLocation() {
  return /^#\/story\/?$/.test(window.location.hash);
}

function cvPageFromLocation() {
  return /^#\/cv\/?$/.test(window.location.hash);
}

function indexPageFromLocation() {
  return /^#\/index\/?$/.test(window.location.hash);
}

function workFromLocation() {
  const match = window.location.hash.match(/^#\/work\/([^/]+)/);
  return match?.[1] ?? null;
}

function parseCsv(text: string): IndexRow[] {
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = "";
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (character === '"') {
      if (quoted && text[index + 1] === '"') {
        cell += '"';
        index += 1;
      } else quoted = !quoted;
    } else if (character === "," && !quoted) {
      row.push(cell);
      cell = "";
    } else if ((character === "\n" || character === "\r") && !quoted) {
      if (character === "\r" && text[index + 1] === "\n") index += 1;
      row.push(cell);
      if (row.some(Boolean)) rows.push(row);
      row = [];
      cell = "";
    } else cell += character;
  }
  if (cell || row.length) rows.push([...row, cell]);
  const [headers, ...values] = rows;
  if (!headers) return [];
  return values
    .map((valuesRow) =>
      Object.fromEntries(headers.map((header, index) => [header.trim(), valuesRow[index]?.trim() ?? ""])),
    )
    .filter((item) => item.show.toLowerCase() === "yes")
    .map((item) => ({
      year: Number(item.year),
      title: item.title,
      type: item.type,
      context: item.context,
      lenses: lensOrder.filter((lens) => item[lens]?.toLowerCase() === "x"),
      image_url: item.image_url,
      link: item.link,
    }));
}

function hashNumber(value: string) {
  return [...value].reduce((hash, character) => ((hash << 5) - hash + character.charCodeAt(0)) | 0, 0);
}

type MotionPatch = {
  element: HTMLSpanElement;
  depth: number;
  textZone: boolean;
};

type MotionEntry = {
  root: HTMLDivElement;
  layers: HTMLElement[];
  patches: MotionPatch[];
  visible: boolean;
};

const motionEntries = new Set<MotionEntry>();
let motionObserver: IntersectionObserver | null = null;

function registerMotionEntry(entry: MotionEntry) {
  motionEntries.add(entry);
  motionObserver?.observe(entry.root);
  return () => {
    motionObserver?.unobserve(entry.root);
    motionEntries.delete(entry);
  };
}

function PatternMotionController() {
  useEffect(() => {
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (reducedMotion.matches) return;

    const patchState = new WeakMap<HTMLElement, { x: number; y: number; opacity: number }>();
    const layerState = new WeakMap<HTMLElement, { x: number; y: number }>();
    let pointerX = innerWidth / 2;
    let pointerY = innerHeight / 2;
    let previousX = pointerX;
    let previousY = pointerY;
    let previousTime = performance.now();
    let speedTarget = 0;
    let speed = 0;
    let frame = 0;

    motionObserver = new IntersectionObserver((observations) => {
      observations.forEach((observation) => {
        const entry = [...motionEntries].find((candidate) => candidate.root === observation.target);
        if (entry) {
          entry.visible = observation.isIntersecting;
          if (!observation.isIntersecting) {
            entry.patches.forEach((patch) => {
              patch.element.style.opacity = "0";
              patchState.set(patch.element, { x: 0, y: 0, opacity: 0 });
            });
          }
        }
      });
    });
    motionEntries.forEach((entry) => motionObserver?.observe(entry.root));

    const trackPointer = (event: PointerEvent) => {
      const now = performance.now();
      const elapsed = Math.max(now - previousTime, 8);
      const velocity = Math.hypot(event.clientX - previousX, event.clientY - previousY) / elapsed;
      speedTarget = Math.max(speedTarget, Math.min(1, velocity / 1.35));
      pointerX = event.clientX;
      pointerY = event.clientY;
      previousX = pointerX;
      previousY = pointerY;
      previousTime = now;
    };

    const animate = () => {
      speedTarget *= 0.88;
      speed += (speedTarget - speed) * 0.08;
      if (speed < 0.001) speed = 0;

      motionEntries.forEach((entry) => {
        if (!entry.visible) return;
        const bounds = entry.root.getBoundingClientRect();
        const relativeX = Math.max(-1, Math.min(1, (pointerX - (bounds.left + bounds.width / 2)) / Math.max(bounds.width / 2, 1)));
        const relativeY = Math.max(-1, Math.min(1, (pointerY - (bounds.top + bounds.height / 2)) / Math.max(bounds.height / 2, 1)));
        const scrollPosition = Math.max(-1, Math.min(1, (bounds.top + bounds.height / 2 - innerHeight / 2) / innerHeight));
        const interactionSurface = entry.root.closest(".work-cover, .work-hero, .project-gallery-image");
        const revealing = entry.root.matches(":hover")
          || entry.root.matches(":focus-within")
          || entry.root.classList.contains("revealed")
          || Boolean(interactionSurface?.matches(":hover, :focus-within"));

        entry.layers.forEach((layer) => {
          const state = layerState.get(layer) ?? { x: 0, y: 0 };
          const targetX = relativeX * -12;
          const targetY = (relativeY + scrollPosition) * -6;
          state.x += (targetX - state.x) * 0.08;
          state.y += (targetY - state.y) * 0.08;
          layer.style.transform = `translate3d(${state.x}px, ${state.y}px, 0) scale(1.04)`;
          layerState.set(layer, state);
        });

        entry.patches.forEach((patch) => {
          const state = patchState.get(patch.element) ?? { x: 0, y: 0, opacity: 0 };
          const targetX = relativeX * 60 * patch.depth;
          const targetY = (relativeY * 60 + scrollPosition * 60) * patch.depth;
          const maximum = patch.textZone ? 0.35 : 0.9;
          const targetOpacity = revealing ? 0 : speed * maximum;
          state.x += (targetX - state.x) * 0.08;
          state.y += (targetY - state.y) * 0.08;
          state.opacity += (targetOpacity - state.opacity) * 0.08;
          patch.element.style.transform = `translate3d(${state.x}px, ${state.y}px, 0)`;
          patch.element.style.opacity = String(state.opacity);
          patchState.set(patch.element, state);
        });
      });
      frame = requestAnimationFrame(animate);
    };

    window.addEventListener("pointermove", trackPointer, { passive: true });
    frame = requestAnimationFrame(animate);
    return () => {
      window.removeEventListener("pointermove", trackPointer);
      cancelAnimationFrame(frame);
      motionObserver?.disconnect();
      motionObserver = null;
    };
  }, []);
  return null;
}

function DitherImage({
  src,
  seed,
  alt = "",
  allowSolid = false,
  revealed = false,
  focusable = true,
}: {
  src: string;
  seed: string;
  alt?: string;
  allowSolid?: boolean;
  revealed?: boolean;
  focusable?: boolean;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const patchRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const [fallback, setFallback] = useState(false);
  const [touchRevealed, setTouchRevealed] = useState(false);
  const value = Math.abs(hashNumber(seed));
  const patchCount = 8 + (value % 7);
  const characters = ["░", "▒", "▓", "█", "▚", "▞", "#", "+", ":", "·", "/", "\\", "=", "×"];
  const patches = Array.from({ length: patchCount }, (_, index) => {
    const patchValue = Math.abs(hashNumber(`${seed}-${index}`));
    const characterPatch = patchValue % 5 >= 2;
    const pattern = allowSolid && index === 0
      ? "solid"
      : characterPatch
        ? "character"
        : ["grid", "dots", "checker"][patchValue % 3];
    const character = characters[patchValue % characters.length];
    const fontSize = 8 + ((patchValue >> 5) % 9);
    const tileWidth = fontSize * 2;
    const tileHeight = Math.round(fontSize * 2.1);
    const svg = pattern === "character"
      ? `<svg xmlns="http://www.w3.org/2000/svg" width="${tileWidth}" height="${tileHeight}"><g fill="#0dff00" font-family="JetBrains Mono,monospace" font-size="${fontSize}px"><text x="0" y="${fontSize}">${character}</text><text x="${fontSize}" y="${fontSize}">${character}</text><text x="0" y="${fontSize * 2}">${character}</text><text x="${fontSize}" y="${fontSize * 2}">${character}</text></g></svg>`
      : "";
    const top = patchValue % 68;
    const height = 5 + ((patchValue >> 9) % 31);
    return {
      pattern,
      left: patchValue % 78,
      top,
      width: 5 + ((patchValue >> 4) % 31),
      height,
      cell: 6 + ((patchValue >> 13) % 11),
      depth: 0.2 + ((patchValue % 81) / 100),
      textZone: top < 18 || top + height > 45,
      image: svg ? `url("data:image/svg+xml,${encodeURIComponent(svg)}")` : undefined,
      imageSize: svg ? `${tileWidth}px ${tileHeight}px` : undefined,
    };
  });

  const drawDither = () => {
    const image = imageRef.current;
    const canvas = canvasRef.current;
    if (!image || !canvas || !image.naturalWidth || !image.naturalHeight) return;
    const width = Math.max(1, Math.round(image.naturalWidth / 3));
    const height = Math.max(1, Math.round(image.naturalHeight / 3));
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) {
      setFallback(true);
      return;
    }
    try {
      context.drawImage(image, 0, 0, width, height);
      const pixels = context.getImageData(0, 0, width, height);
      const bayer = [
        [0, 8, 2, 10],
        [12, 4, 14, 6],
        [3, 11, 1, 9],
        [15, 7, 13, 5],
      ];
      for (let y = 0; y < height; y += 1) {
        for (let x = 0; x < width; x += 1) {
          const offset = (y * width + x) * 4;
          const gray = pixels.data[offset] * 0.299 + pixels.data[offset + 1] * 0.587 + pixels.data[offset + 2] * 0.114;
          const threshold = ((bayer[y % 4][x % 4] + 0.5) / 16) * 255;
          const output = gray > threshold ? 255 : 0;
          pixels.data[offset] = output;
          pixels.data[offset + 1] = output;
          pixels.data[offset + 2] = output;
          pixels.data[offset + 3] = 255;
        }
      }
      context.putImageData(pixels, 0, 0);
      setFallback(false);
    } catch {
      setFallback(true);
    }
  };

  useEffect(() => {
    const root = rootRef.current;
    const image = imageRef.current;
    const canvas = canvasRef.current;
    if (!root || !image || !canvas) return;
    const motionPatches = patchRefs.current.flatMap((element, index) =>
      element ? [{ element, depth: patches[index].depth, textZone: patches[index].textZone }] : [],
    );
    return registerMotionEntry({
      root,
      layers: [image, canvas],
      patches: motionPatches,
      visible: false,
    });
  }, [seed]);

  const isRevealed = revealed || touchRevealed;
  return (
    <div
      className={`dither-image ${fallback ? "fallback" : ""} ${isRevealed ? "revealed" : ""}`}
      ref={rootRef}
      tabIndex={focusable ? 0 : -1}
      onClick={() => {
        if (window.matchMedia("(pointer: coarse)").matches) setTouchRevealed(true);
      }}
    >
      <img
        ref={imageRef}
        src={src}
        alt={alt}
        crossOrigin="anonymous"
        onLoad={drawDither}
        onError={(event) => {
          const image = event.currentTarget;
          if (image.dataset.corsRetried) return;
          image.dataset.corsRetried = "true";
          image.removeAttribute("crossorigin");
          image.src = `${src}${src.includes("?") ? "&" : "?"}cors-fallback=1`;
          setFallback(true);
        }}
      />
      <canvas ref={canvasRef} className="dither-canvas" aria-hidden="true" />
      <span className="cors-fallback" aria-hidden="true" />
      {patches.map((patch, index) => (
        <span
          className={`pattern-patch pattern-${patch.pattern}`}
          key={`${seed}-${patch.pattern}-${index}`}
          ref={(element) => { patchRefs.current[index] = element; }}
          style={{
            left: `${patch.left}%`,
            top: `${patch.top}%`,
            width: `${patch.width}%`,
            height: `${patch.height}%`,
            backgroundSize: patch.imageSize ?? `${patch.cell}px ${patch.cell}px`,
            backgroundImage: patch.image,
          }}
          aria-hidden="true"
        />
      ))}
    </div>
  );
}

function AsciiStrip() {
  const ref = useRef<HTMLDivElement>(null);
  const [count, setCount] = useState(120);
  const [cursor, setCursor] = useState(50);
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => {
      const fontSize = parseFloat(getComputedStyle(element).fontSize) || 13;
      const charWidth = fontSize * 0.6 + fontSize * 0.13;
      setCount(Math.ceil(element.clientWidth / charWidth) + 2);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const characters = Array.from({ length: count }, (_, index) => {
    const position = (index / Math.max(count - 1, 1)) * 100;
    const distance = Math.abs(position - cursor);
    if (distance < 4) return "█";
    if (distance < 10) return "▓";
    if (distance < 20) return "▒";
    return "░";
  }).join("");
  return (
    <div
      className="ascii-strip"
      ref={ref}
      aria-hidden="true"
      onPointerMove={(event) => {
        const bounds = event.currentTarget.getBoundingClientRect();
        setCursor(((event.clientX - bounds.left) / bounds.width) * 100);
      }}
    >
      {characters}
    </div>
  );
}

