// large portfolio photos live in their own file (src/data/photos.json) so App.tsx stays light
const PHOTOS = (dataFiles["./data/photos.json"] ?? {}) as Record<string, string>;
const GALLERY = (dataFiles["./data/gallery.json"] ?? {}) as Record<string, string>;
const flowSourceOne = (src: string) => (src.startsWith("embedded:") ? FLOW_IMAGES[src.slice(9)] ?? "" : src.startsWith("photo:") ? PHOTOS[src.slice(6)] ?? "" : src.startsWith("gallery:") ? GALLERY[src.slice(8)] ?? "" : src);
const flowSource = (src: string) => src.split("||").map(flowSourceOne).find(Boolean) ?? "";

/* ---------- a desk of cards: materials dealt out, slightly messy, named on hover ---------- */
function CardDesk({ items, caption }: { items: { src: string; label: string; href?: string; w: number; h: number }[]; caption?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [dealt, setDealt] = useState(false);
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setDealt(true); observer.disconnect(); } }, { threshold: 0.25 });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const columns = 4;
  return (
    <figure className={`card-desk ${dealt ? "dealt" : ""}`} ref={ref}>
      <div className="card-desk-surface">
        {items.map((item, index) => {
          const seed = Math.sin(index * 12.9898) * 43758.5453;
          const random = seed - Math.floor(seed);
          const column = index % columns;
          const row = Math.floor(index / columns);
          const style = {
            "--x": `${8 + column * 23 + (random - 0.5) * 8}%`,
            "--y": `${6 + row * 30 + ((random * 7) % 1 - 0.5) * 10}%`,
            "--r": `${(random - 0.5) * 22}deg`,
            "--delay": `${index * 70}ms`,
            "--ratio": `${item.w} / ${item.h}`,
          } as React.CSSProperties;
          const card = (
            <>
              <img src={flowSource(item.src)} alt="" loading="lazy" />
              <span className="card-label">{item.label}</span>
            </>
          );
          return item.href
            ? <a className="desk-card" style={style} href={item.href} target="_blank" rel="noreferrer" key={item.label} aria-label={`${item.label}, opens the file`}>{card}</a>
            : <span className="desk-card" style={style} key={item.label}>{card}</span>;
        })}
      </div>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ---------- hero slideshow: a short, calm walk through a place ---------- */
function HeroSlideshow({ slides, credit }: { slides: string[]; credit?: string }) {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    if (paused || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const timer = window.setTimeout(() => setIndex((value) => (value + 1) % slides.length), 4500);
    return () => window.clearTimeout(timer);
  }, [index, paused, slides.length]);
  const go = (step: number) => setIndex((value) => (value + step + slides.length) % slides.length);
  return (
    <div className="hero-slideshow" onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      {slides.map((src, slideIndex) => (
        <img
          className={`work-hero-photo slide ${slideIndex === index ? "on" : ""}`}
          src={src}
          alt=""
          loading={slideIndex === 0 ? "eager" : "lazy"}
          key={src.slice(-40) + slideIndex}
        />
      ))}
      <div className="slideshow-controls">
        <button onClick={() => go(-1)} aria-label="previous photo">←</button>
        <span>{String(index + 1).padStart(2, "0")} / {String(slides.length).padStart(2, "0")}</span>
        <button onClick={() => go(1)} aria-label="next photo">→</button>
      </div>
      {credit && <small className="slideshow-credit">{credit}</small>}
    </div>
  );
}

/* ---------- project flow: the original page, image by image, embed by embed ---------- */
type FlowBlock =
  | { type: "images"; items: { src: string; w: number; h: number }[]; caption?: string }
  | { type: "video"; src: string; w: number; h: number }
  | { type: "embed"; src: string; w: number; h: number; label?: string }
  | { type: "link"; href: string; label: string }
  | { type: "slideshow"; items: string[]; credit?: string }
  | { type: "marquee"; items: string[]; credit?: string }
  | { type: "scroll"; src: string; caption?: string }
  | { type: "deck"; items: { src: string; label: string; href?: string; w: number; h: number }[]; caption?: string };
function ProjectFlow({ blocks, title, maxWidth }: { blocks: FlowBlock[]; title: string; maxWidth?: number }) {
  return (
    <section className="work-flow" aria-label={`${title}, project images and media`} style={maxWidth ? ({ "--flow-max": `${maxWidth}px` } as React.CSSProperties) : undefined}>
      {blocks.map((block, index) => {
        if (block.type === "deck") {
          return <CardDesk items={block.items} caption={block.caption} key={index} />;
        }
        if (block.type === "scroll") {
          const src = flowSource(block.src);
          if (!src) return null;
          return (
            <figure className="flow-scroll" key={index}>
              <div className="flow-scroll-frame"><img src={src} alt="" loading="lazy" /></div>
              <figcaption>{block.caption ?? "scroll inside the image ↓"}</figcaption>
            </figure>
          );
        }
        if (block.type === "marquee") {
          const photos = block.items.map(flowSource).filter(Boolean);
          if (!photos.length) return null;
          return (
            <figure className="flow-marquee" key={index}>
              <div className="marquee-track">
                {[...photos, ...photos].map((src, photoIndex) => <img src={src} alt="" key={photoIndex} />)}
              </div>
              {block.credit && <figcaption>{block.credit}</figcaption>}
            </figure>
          );
        }
        if (block.type === "slideshow") {
          const slides = block.items.map(flowSource).filter(Boolean);
          if (!slides.length) return null;
          return (
            <div className="flow-slideshow" key={index}>
              <HeroSlideshow slides={slides} credit={block.credit} />
            </div>
          );
        }
        if (block.type === "images" && block.items.every((item) => !flowSource(item.src))) return null;
        if (block.type === "images") {
          const row = (
            <div className="flow-row" key={index}>
              {block.items.map((item) => (
                <img
                  src={flowSource(item.src)}
                  alt=""
                  loading="lazy"
                  style={item.w && item.h ? { flexGrow: item.w / item.h, aspectRatio: `${item.w} / ${item.h}` } : { flexGrow: 1 }}
                  onLoad={(event) => {
                    // never enlarge a photo beyond its own resolution
                    if (block.items.length === 1) event.currentTarget.style.maxWidth = `${event.currentTarget.naturalWidth}px`;
                  }}
                  key={item.src}
                />
              ))}
            </div>
          );
          if (!block.caption) return row;
          return (
            <figure className="flow-figure" key={index}>
              {row}
              <figcaption>{block.caption}</figcaption>
            </figure>
          );
        }
        if (block.type === "video") {
          return (
            <div className="flow-media" style={{ aspectRatio: `${block.w} / ${block.h}` }} key={index}>
              <video src={block.src} controls playsInline preload="metadata" />
            </div>
          );
        }
        if (block.type === "embed") {
          const ratio = block.w / block.h;
          return (
            <div className={`flow-media ${ratio < 1 ? "tall" : ""}`} style={{ aspectRatio: `${block.w} / ${block.h}` }} key={index}>
              <iframe src={block.src} title={block.label ?? `${title}, embedded media`} loading="lazy" allow="autoplay; fullscreen; xr-spatial-tracking" allowFullScreen />
            </div>
          );
        }
        return (
          <a className="flow-link" href={block.href} target="_blank" rel="noreferrer" key={index}>
            <span>{block.label}</span><span>↗</span>
          </a>
        );
      })}
    </section>
  );
}

/* ---------- project sections: headed chapters below the main flow ---------- */
type WorkSection = { title: string; text?: string; items?: string[]; flow?: FlowBlock[] };
function WorkSections({ sections, title }: { sections: WorkSection[]; title: string }) {
  const visible = sections.filter((section) => section.text || section.items?.length || section.flow?.length);
  if (!visible.length) return null;
  return (
    <div className="work-sections">
      {visible.map((section) => (
        <section className="work-section" key={section.title}>
          <header>
            <h2>{section.title}</h2>
            {section.text && <p>{section.text}</p>}
            {section.items && section.items.length > 0 && <ul>{section.items.map((item) => <li key={item}>{item}</li>)}</ul>}
          </header>
          {section.flow && section.flow.length > 0 && <ProjectFlow blocks={section.flow} title={`${title}, ${section.title}`} />}
        </section>
      ))}
    </div>
  );
}

function WorkPage({
  work,
  selected,
  onBack,
  onOpen,
  onLens,
}: {
  work: Work;
  selected: Lens[];
  onBack: () => void;
  onOpen: (id: string) => void;
  onLens: (lens: Lens) => void;
}) {
  const index = content.works.findIndex((candidate) => candidate.id === work.id);
  const previous = content.works[(index - 1 + content.works.length) % content.works.length];
  const next = content.works[(index + 1) % content.works.length];
  const image = flowSource(work.image || "") || WORK_IMAGES[work.id];
  const gallery = ((work as Work & { gallery?: string[] }).gallery ?? []).filter(Boolean);
  const heroVideo = (work as Work & { hero_video?: string }).hero_video;
  const slides = ((work as Work & { slides?: string[] }).slides ?? []).map(flowSource).filter(Boolean);
  const baseFlow = (work as Work & { flow?: FlowBlock[] }).flow ?? [];
  const flow: FlowBlock[] = baseFlow;

  useEffect(() => { window.scrollTo(0, 0); }, [work.id]);

  return (
    <main className="work-page">
      <section className={`work-hero ${image || heroVideo ? "has-image" : "no-image"}`}>
        {heroVideo
          ? <video className="work-hero-photo" src={heroVideo} autoPlay muted loop playsInline controls />
          : slides.length > 1
            ? <HeroSlideshow slides={slides} credit={(work as Work & { slides_credit?: string }).slides_credit} />
            : image && <img className="work-hero-photo" src={image} alt="" />}
        {(work as Work & { image_credit?: string }).image_credit && <small className="slideshow-credit hero-credit">{(work as Work & { image_credit?: string }).image_credit}</small>}
        <button onClick={onBack}>← all works</button>
        <h1>
          {work.title.split(" ").map((word, wordIndex) => (
            <span className="word-mask" key={`${word}-${wordIndex}`}>
              <i style={{ animationDelay: `${wordIndex * 55}ms` }}>{word}&nbsp;</i>
            </span>
          ))}
        </h1>
        <p>
          {work.question.split(" ").map((word, wordIndex) => (
            <span className="word-mask" key={`${word}-${wordIndex}`}>
              <i style={{ animationDelay: `${250 + wordIndex * 40}ms` }}>{word}&nbsp;</i>
            </span>
          ))}
        </p>
      </section>
      <section className="work-body">
        <aside className="work-facts">
          <dl><dt>year</dt><dd>{work.year}</dd></dl>
          <dl><dt>made</dt><dd>{creditLine(work).split(" · ").slice(1).join(" · ") || "—"}</dd></dl>
          <dl><dt>field</dt><dd>{work.tag}</dd></dl>
          <dl><dt>role</dt><dd>{work.role}</dd></dl>
          {"tools" in work && work.tools && <dl><dt>tools</dt><dd>{work.tools}</dd></dl>}
          <dl>
            <dt>versions</dt>
            <dd>{work.lenses.map((lens) => (
              <button onClick={() => onLens(lens as Lens)} key={lens}>/{lens}</button>
            ))}</dd>
          </dl>
          <LookingBack work={work} />
        </aside>
        <article className="work-story">
          <h2>{work.context_line}</h2>
          <p>{work.text}</p>
          {(work as Work & { bullets?: { title: string; items: string[] } }).bullets && (() => {
            const bullets = (work as Work & { bullets: { title: string; items: string[] } }).bullets;
            return (
              <div className="work-bullets">
                <h3>{bullets.title}</h3>
                <ul>{bullets.items.map((item) => <li key={item}>{item}</li>)}</ul>
              </div>
            );
          })()}
          {"question_note" in work && work.question_note && <p className="placeholder-note">{work.question_note}</p>}
          {!flow.length && gallery.map((url) => (
            <img className="project-gallery-photo" src={url} alt="" loading="lazy" key={url} />
          ))}
        </article>
      </section>
      {flow.length > 0 && <ProjectFlow blocks={flow} title={work.title} maxWidth={(work as Work & { flow_max?: number }).flow_max} />}
      {(work as Work & { sections?: WorkSection[] }).sections && <WorkSections sections={(work as Work & { sections: WorkSection[] }).sections} title={work.title} />}
      <nav className="project-pagination" aria-label="Project pagination">
        <button onClick={() => onOpen(previous.id)}>← {previous.title}</button>
        <button onClick={() => onOpen(next.id)}>{next.title} →</button>
      </nav>
      <div className="work-page-print">
        <p>{work.context_line}</p><p>{work.text}</p>
      </div>
    </main>
  );
}

function LensSlots({ lenses }: { lenses: readonly string[] }) {
  return (
    <span className="lens-slots" tabIndex={0}>
      {lensOrder.map((lens) => (
        <span className={`slot ${lenses.includes(lens) ? "on" : ""}`} key={lens}><LensIcon lens={lens} on={lenses.includes(lens)} /></span>
      ))}
      <em role="tooltip">
        {lenses.length ? lenses.map((lens) => `/${lens}`).join(" + ") : "no version yet"}
      </em>
    </span>
  );
}

function IndexSection({ full = false }: { full?: boolean }) {
  const [rows, setRows] = useState<IndexRow[]>((dataFiles["./data/index.json"] ?? INDEX_FALLBACK) as IndexRow[]);
  const [search, setSearch] = useState("");
  const [context, setContext] = useState("all");
  const [ascending, setAscending] = useState(false);
  const [hoverImage, setHoverImage] = useState<{ url: string; x: number; y: number } | null>(null);
  const previewCount = Number(content.ui.index_preview_count) || 12;

  useEffect(() => {
    if (!SHEET_CSV_URL) return;
    fetch(SHEET_CSV_URL)
      .then((response) => {
        if (!response.ok) throw new Error("CSV unavailable");
        return response.text();
      })
      .then((csv) => {
        const parsed = parseCsv(csv);
        if (parsed.length) setRows(parsed);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => { if (full) window.scrollTo(0, 0); }, [full]);

  const contexts = [...new Set(rows.map((row) => row.context).filter(Boolean))].sort();
  const filtered = rows
    .filter((row) => context === "all" || row.context === context)
    .filter((row) => `${row.title} ${row.type} ${row.context}`.toLowerCase().includes(search.toLowerCase()))
    .sort((first, second) => ascending ? first.year - second.year : second.year - first.year);
  const visibleRows = full || search || context !== "all" ? filtered : filtered.slice(0, previewCount);

  return (
    <section className={`index-section ${full ? "full" : ""}`} id="index">
      {full && <button className="back-link" onClick={() => { window.location.hash = "#/"; }}>← back to the site</button>}
      <div className="index-heading">
        <h2>{content.ui.index_title}</h2>
        <p className="index-sub">{content.ui.index_sub} · {rows.length} entries</p>
      </div>
      <div className="index-legend">
        <span>{content.ui.index_legend}</span>
        {lensOrder.map((lens) => (
          <span key={lens} className="legend-item"><LensIcon lens={lens} on /> /{lens}</span>
        ))}
      </div>
      <div className="index-controls">
        <input aria-label="Search index" placeholder="search the archive…" value={search} onChange={(event) => setSearch(event.target.value)} />
        <select aria-label="Filter by context" value={context} onChange={(event) => setContext(event.target.value)}>
          <option value="all">all contexts</option>
          {contexts.map((item) => <option key={item}>{item}</option>)}
        </select>
        {full && <button className="index-print" onClick={() => window.print()}>print / save as pdf ↓</button>}
      </div>
      <div className="index-table">
        <div className="index-row index-head">
          <button onClick={() => setAscending((value) => !value)}>year {ascending ? "↑" : "↓"}</button>
          <span>title</span><span>type</span><span>context</span><span>related</span>
        </div>
        {visibleRows.map((row, index) => (
          <div
            className="index-row"
            key={`${row.title}-${row.year}-${index}`}
            onPointerMove={(event) => row.image_url && setHoverImage({ url: row.image_url, x: event.clientX, y: event.clientY })}
            onPointerLeave={() => setHoverImage(null)}
          >
            <span>{row.year}</span>
            <span>
              {row.work && content.works.some((work) => work.id === row.work && !JSON.stringify(work).includes("PLACEHOLDER"))
                ? <button className="on-site" onClick={() => { window.location.hash = `#/work/${row.work}`; }}>{row.title}</button>
                : row.link ? <a href={row.link} target="_blank" rel="noreferrer">{row.title}</a> : row.title}
              {row.type && <small className="row-type">{row.type}</small>}
            </span>
            <span>{row.type}</span><span>{row.context || "—"}</span>
            <LensSlots lenses={row.lenses} />
          </div>
        ))}
      </div>
      {!full && visibleRows.length < filtered.length && (
        <button className="index-all" onClick={() => { window.location.hash = "#/index"; }}>
          {content.ui.index_all} ({filtered.length}) →
        </button>
      )}
      {hoverImage && <img className="index-thumbnail" src={hoverImage.url} alt="" style={{ left: hoverImage.x + 18, top: hoverImage.y + 18 }} />}
    </section>
  );
}

function Footer() {
  return (
    <footer id="contact">
      <div className="footer-grid">
        <div>
          <CyclingIcon className="footer-avatar" />
          <h2>{content.ui.contact_title}</h2>
          <p>{content.ui.contact_sub}</p>
        </div>
        <ContactForm />
      </div>
      <p className="footer-line">{content.meta.name} · portfolio {new Date().getFullYear()} · eylosh v{content.meta.build}</p>
    </footer>
  );
}

/* ---------- favicon: the same heart that turns into the five versions ---------- */
function startCyclingFavicon() {
  if (typeof document === "undefined") return;
  const canvas = document.createElement("canvas");
  canvas.width = 32;
  canvas.height = 32;
  const context = canvas.getContext("2d");
  if (!context) return;
  const links = () => {
    const found = [...document.querySelectorAll<HTMLLinkElement>('link[rel~="icon"]')];
    if (found.length) return found;
    const link = document.createElement("link");
    link.rel = "icon";
    document.head.appendChild(link);
    return [link];
  };
  let index = 0;
  const draw = () => {
    const icon = PENDANTS[index] === "heart" ? PENDANT_HEART : PIXELS[PENDANTS[index]];
    context.clearRect(0, 0, 32, 32);
    context.fillStyle = "#000";
    context.fillRect(0, 0, 32, 32);
    context.fillStyle = "#0dff00";
    icon.forEach((row, y) => [...row].forEach((char, x) => { if (char === "#") context.fillRect(2 + x * 4, 2 + y * 4, 4, 4); }));
    const url = canvas.toDataURL("image/png");
    links().forEach((link) => { link.type = "image/png"; link.href = url; });
    index = (index + 1) % PENDANTS.length;
  };
  draw();
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  window.setInterval(draw, 1500);
}

function App() {
  useEffect(() => { startCyclingFavicon(); }, []);
  useEffect(() => {
    // old links like /portfolio or /contact land on a section of the home page
    const anchor = window.location.hash;
    if (anchor === "#works" || anchor === "#contact") {
      window.setTimeout(() => document.getElementById(anchor.slice(1))?.scrollIntoView(), 700);
    }
  }, []);
  const [selected, setSelected] = useState<Lens[]>(lensesFromLocation);
  const [workId, setWorkId] = useState<string | null>(workFromLocation);
  const [indexPage, setIndexPage] = useState(indexPageFromLocation);
  const [cvPage, setCvPage] = useState(cvPageFromLocation);
  const [storyPage, setStoryPage] = useState(storyPageFromLocation);
  const [contactOpen, setContactOpen] = useState(false);
  const [catWalking, setCatWalking] = useState(false);

  useEffect(() => {
    const syncRoute = () => {
      const nextWork = workFromLocation();
      setWorkId(nextWork);
      setIndexPage(indexPageFromLocation());
      setCvPage(cvPageFromLocation());
      setStoryPage(storyPageFromLocation());
      if (storyPageFromLocation()) window.scrollTo(0, 0);
      if (!nextWork && !indexPageFromLocation() && !cvPageFromLocation() && !storyPageFromLocation()) setSelected(lensesFromLocation());
    };
    window.addEventListener("hashchange", syncRoute);
    return () => window.removeEventListener("hashchange", syncRoute);
  }, []);

  useEffect(() => {
    let typed = "";
    const listen = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setContactOpen(false);
        return;
      }
      if (event.key.length !== 1) return;
      typed = `${typed}${event.key.toLowerCase()}`.slice(-3);
      if (typed === "cat") {
        setCatWalking(false);
        requestAnimationFrame(() => setCatWalking(true));
        window.setTimeout(() => setCatWalking(false), 7000);
      }
    };
    window.addEventListener("keydown", listen);
    return () => window.removeEventListener("keydown", listen);
  }, []);

  const combinationLine = useMemo(() => {
    if (!selected.length) return content.combinations._none;
    if (selected.length === 1) return content.lenses[selected[0]].line;
    if (selected.length === 2) {
      const key = [...selected].sort().join("+") as keyof typeof content.combinations;
      if (content.combinations[key]) return content.combinations[key];
    }
    if (selected.length === 5) return content.combinations._all;
    const cores = selected.map((lens) => (content.lenses[lens] as { core?: string }).core ?? lens);
    const list = `${cores.slice(0, -1).join(", ")} and ${cores[cores.length - 1]}`;
    return content.combinations._three_or_four.replace("{list}", list);
  }, [selected]);

  const matchingCount = (lenses: readonly string[]) => selected.filter((lens) => lenses.includes(lens)).length;
  const sortedWorks = useMemo(
    () => [...content.works].sort((first, second) =>
      matchingCount(second.lenses) - matchingCount(first.lenses)
      || Number(second.featured) - Number(first.featured)
      || Number.parseInt(second.year) - Number.parseInt(first.year),
    ),
    [selected],
  );
  // only finished works (real photo + real text) are shown as cards; everything else lives in the archive list
  const isShowcase = (work: Work) => Boolean((work as Work & { featured?: boolean }).featured) && Boolean(flowSource(work.image || "") || WORK_IMAGES[work.id]) && !JSON.stringify(work).includes("PLACEHOLDER");
  const showcase = sortedWorks.filter(isShowcase);
  const mainWorks = selected.length ? showcase.filter((work) => matchingCount(work.lenses)) : showcase;
  // unfinished drafts (still marked PLACEHOLDER) stay off the public site until they are written
  const archiveWorks = sortedWorks.filter((work) => !mainWorks.includes(work) && !JSON.stringify(work).includes("PLACEHOLDER"));

  const toggleLens = (lens: Lens) => {
    const next = selected.includes(lens) ? selected.filter((item) => item !== lens) : [...selected, lens];
    setSelected(next);
    window.history.replaceState(null, "", next.length ? `#/${next.join("+")}` : "#/");
  };
  const clearLenses = () => {
    setSelected([]);
    window.history.replaceState(null, "", "#/");
  };
  const openWork = (id: string) => { window.location.hash = `#/work/${id}`; };
  const backToWorks = () => {
    window.location.hash = selected.length ? `#/${selected.join("+")}` : "#/";
    window.setTimeout(() => document.getElementById("works")?.scrollIntoView(), 0);
  };
  const selectFromWork = (lens: Lens) => {
    setSelected([lens]);
    window.location.hash = `#/${lens}`;
    window.setTimeout(() => document.getElementById("history")?.scrollIntoView(), 0);
  };
  const activeWork = workId ? content.works.find((work) => work.id === workId) : undefined;

  return (
    <>
      <PatternMotionController />
      <TopBar selected={selected} onContact={() => setContactOpen(true)} />
      <ContactDrawer open={contactOpen} onClose={() => setContactOpen(false)} />
      {activeWork ? (
        <WorkPage
          work={activeWork}
          selected={selected}
          onBack={backToWorks}
          onOpen={openWork}
          onLens={selectFromWork}
        />
      ) : cvPage ? (
        <CvPage />
      ) : storyPage ? (
        <main className="story-page">
          <div className="story-page-head">
            <button onClick={() => { window.location.hash = selected.length ? `#/${selected.join("+")}` : "#/"; }}>← back to the site</button>
          </div>
          <BuildHistory
            selected={selected}
            combinationLine={combinationLine}
            matchTotal={mainWorks.length}
            onToggle={toggleLens}
            onClear={clearLenses}
            onOpenWork={openWork}
          />
        </main>
      ) : indexPage ? (
        <main className="index-page"><IndexSection full /></main>
      ) : (
        <main>
          <Intro />
          <BuildHistory
            selected={selected}
            combinationLine={combinationLine}
            matchTotal={mainWorks.length}
            onToggle={toggleLens}
            onClear={clearLenses}
            onOpenWork={openWork}
          />
          <Works selected={selected} works={mainWorks} archive={archiveWorks} onOpen={openWork} />
          <IndexSection />
        </main>
      )}
      <Footer />
      {catWalking && <pre className="walking-cat" aria-label="A walking ASCII cat">{`/\\_/\\\\\n( o.o )\n > ^ <`}</pre>}
    </>
  );
}

export default App;
